ICON_NAMES = frozenset(_PATHS)


def icon(name: str, size: int = 13, label: str | None = None, stroke: float = 2.0) -> str:
    """Inline SVG for `name`, sized to sit on a line of text.

    Decorative by default (hidden from screen readers). Pass `label` when the
    icon is the only thing carrying the meaning, e.g. the protected-area turtle.
    """
    paths = _PATHS[name]
    a11y = (f'role="img" aria-label="{escape(label)}"><title>{escape(label)}</title>'
            if label else 'aria-hidden="true">')
    # Kept short on purpose: the Conoce panel has a byte budget, and inline
    # SVG in HTML needs no xmlns.
    return (
        f'<svg class="ic ic-{name}" width="{size}" height="{size}" viewBox="0 0 24 24" '
        f'fill="none" stroke="currentColor" stroke-width="{stroke:g}" stroke-linecap="round" '
        f'stroke-linejoin="round" style="vertical-align:-.15em" {a11y}{paths}</svg>'
    )
